#[cfg(feature = "io")]
mod io {
    use super::Xorcism;
    use std::io::{self, Read, Write};

    pub struct Reader<R: Read> {
        inner: R,
        key: &'static [u8],
        position: usize,
    }

    pub struct Writer<W: Write> {
        inner: W,
        key: &'static [u8],
        position: usize,
    }

    impl<R: Read> Read for Reader<R> {
        fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
            let len = self.inner.read(buf)?;
            for (i, b) in buf.iter_mut().enumerate().take(len) {
                *b ^= self.key[(self.position + i) % self.key.len()];
            }
            self.position = (self.position + len) % self.key.len();
            Ok(len)
        }
    }

    impl<W: Write> Write for Writer<W> {
        fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
            let mut out = vec![0u8; buf.len()];
            for (i, b) in buf.iter().enumerate() {
                out[i] = *b ^ self.key[(self.position + i) % self.key.len()];
            }
            self.position = (self.position + buf.len()) % self.key.len();
            self.inner.write_all(&out)?;
            Ok(buf.len())
        }

        fn flush(&mut self) -> io::Result<()> {
            self.inner.flush()
        }
    }
}
